/**
 * Python-flavoured exception types.
 *
 * The original script lets exceptions escape `main()`, so the interpreter
 * prints a traceback and exits with status 1.  Keeping a distinct class per
 * Python exception lets the entry point reproduce the final traceback line
 * ("ValueError: ...", "IndexError: ...") verbatim.
 */

export class PyError extends Error {
  constructor(pyName, message) {
    super(message);
    this.pyName = pyName;
  }
}

export class PyValueError extends PyError {
  constructor(message) {
    super('ValueError', message);
  }
}

export class PyIndexError extends PyError {
  constructor(message) {
    super('IndexError', message);
  }
}

