/**
 * Small re-implementations of the CPython builtins the script relies on:
 * `repr()` for strings and `int()` for strings.
 */

import { PyValueError } from './pyerrors.mjs';

const REPR_ESCAPES = new Map([
  ['\\', '\\\\'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

/**
 * `repr()` of a Python str: single quotes by default, double quotes when the
 * value contains a single quote but no double quote.  Used by the error
 * messages of `int()` and of argparse's type conversion.
 */
export function pyRepr(value) {
  const quote = value.includes("'") && !value.includes('"') ? '"' : "'";
  let out = '';
  for (const ch of value) {
    if (REPR_ESCAPES.has(ch)) {
      out += REPR_ESCAPES.get(ch);
    } else if (ch === quote) {
      out += '\\' + ch;
    } else {
      out += ch;
    }
  }
  return quote + out + quote;
}

// Python's int() strips leading/trailing whitespace before parsing.
const WHITESPACE = /^[\s﻿ ]+|[\s﻿ ]+$/g;

// Optional sign, then digits that may be grouped by single underscores.
const INT_LITERAL = /^[+-]?[0-9](?:_?[0-9])*$/;

/**
 * `int(text)` with base 10.
 *
 * Accepts surrounding whitespace, an optional sign and PEP 515 underscore
 * separators; anything else raises ValueError with CPython's exact wording.
 */
export function pyInt(text) {
  const stripped = text.replace(WHITESPACE, '');
  if (!INT_LITERAL.test(stripped)) {
    throw new PyValueError(
      `invalid literal for int() with base 10: ${pyRepr(text)}`,
    );
  }
  return Number(stripped.replace(/_/g, ''));
}

