/**
 * A focused re-implementation of the slice of `argparse` used by test4.py:
 * required keyword-only options, `type=int` conversion, `-h/--help`, prefix
 * abbreviation, and argparse's special handling of negative numbers.
 *
 * Errors go to stderr and exit with status 2, matching CPython.
 */

import { pyRepr } from './pytypes.mjs';

// argparse treats "-1" / "-.5" as values rather than options as long as no
// registered option string itself looks like a negative number.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

export class ArgumentParser {
  constructor({ prog }) {
    this.prog = prog;
    this.actions = [
      { flags: ['-h', '--help'], dest: 'help', isHelp: true },
    ];
  }

  /**
   * Mirrors `parser.add_argument("--x", type=..., required=...)`.
   */
  addArgument(flag, { type = String, required = false } = {}) {
    const dest = flag.replace(/^-+/, '');
    this.actions.push({
      flags: [flag],
      dest,
      type,
      required,
      metavar: dest.toUpperCase(),
    });
    return this;
  }

  formatUsage() {
    const parts = ['[-h]'];
    for (const action of this.actions) {
      if (action.isHelp) continue;
      const spec = `${action.flags[0]} ${action.metavar}`;
      parts.push(action.required ? spec : `[${spec}]`);
    }
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    let out = `${this.formatUsage()}\noptions:\n`;
    out += '  -h, --help  show this help message and exit\n';
    for (const action of this.actions) {
      if (action.isHelp) continue;
      out += `  ${action.flags[0]} ${action.metavar}\n`;
    }
    return out;
  }

  /** Print usage + message to stderr and exit(2), like argparse's error(). */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** Resolve a token such as "--a" or an unambiguous abbreviation of it. */
  #lookup(token) {
    const exact = this.actions.find((action) => action.flags.includes(token));
    if (exact) return exact;

    if (!token.startsWith('--')) return null;
    const matches = this.actions.filter((action) =>
      action.flags.some((flag) => flag.startsWith(token)),
    );
    const unique = [...new Set(matches)];
    if (unique.length === 1) return unique[0];
    if (unique.length > 1) {
      const names = unique
        .flatMap((action) => action.flags)
        .filter((flag) => flag.startsWith(token))
        .join(', ');
      this.error(`ambiguous option: ${token} could match ${names}`);
    }
    return null;
  }

  /** True when the token should be read as an option rather than a value. */
  #looksLikeOption(token) {
    if (!token.startsWith('-')) return false;
    if (token === '-' || token === '--') return false;
    if (NEGATIVE_NUMBER.test(token)) return false;
    return !token.includes(' ');
  }

  parseArgs(argv) {
    const values = {};
    const extras = [];

    for (let i = 0; i < argv.length; i += 1) {
      const token = argv[i];

      if (!this.#looksLikeOption(token)) {
        extras.push(token);
        continue;
      }

      // "--a=value" carries its value inline.
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const inline = eq === -1 ? null : token.slice(eq + 1);

      const action = this.#lookup(name);
      if (!action) {
        extras.push(token);
        continue;
      }

      if (action.isHelp) {
        process.stdout.write(this.formatHelp());
        process.exit(0);
      }

      let raw = inline;
      if (raw === null) {
        const next = argv[i + 1];
        if (next === undefined || this.#looksLikeOption(next)) {
          this.error(`argument ${action.flags[0]}: expected one argument`);
        }
        raw = next;
        i += 1;
      }

      try {
        values[action.dest] = action.type === Number ? action.type(raw) : raw;
      } catch (err) {
        this.error(
          `argument ${action.flags[0]}: invalid int value: ${pyRepr(raw)}`,
        );
      }
    }

    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    const missing = this.actions
      .filter((action) => !action.isHelp && action.required)
      .filter((action) => values[action.dest] === undefined)
      .map((action) => action.flags[0]);
    if (missing.length > 0) {
      this.error(
        `the following arguments are required: ${missing.join(', ')}`,
      );
    }

    return values;
  }
}

