/**
 * The Bech32 alphabet plus the two checksum constants that distinguish
 * Bech32 (BIP-173) from Bech32m (BIP-350).
 */

import { PyIndexError } from './pyerrors.mjs';

export const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';

export const BECH32M_CONST = 0x2bc830a3;

export const Encoding = Object.freeze({
  BECH32: 'BECH32',
  BECH32M: 'BECH32M',
});

/**
 * `CHARSET[index]` with CPython's string-indexing semantics: negative indices
 * count from the end, and anything outside [-32, 31] raises IndexError.
 *
 * The reference encoder indexes the charset with the witness version *before*
 * validating it, so this quirk is observable: `--b -1` silently encodes as
 * "l" (and is rejected later by the round-trip check), while `--b 32` aborts
 * with a traceback.
 */
export function charsetAt(index) {
  const resolved = index < 0 ? CHARSET.length + index : index;
  if (!Number.isInteger(resolved) || resolved < 0 || resolved >= CHARSET.length) {
    throw new PyIndexError('string index out of range');
  }
  return CHARSET[resolved];
}

/** `CHARSET.find(ch)`: the 5-bit value of a character, or -1 when absent. */
export function charsetIndexOf(ch) {
  return CHARSET.indexOf(ch);
}

