/**
 * General base conversion between bit widths (8 <-> 5 for segwit programs).
 */

/**
 * Regroup `data` from `fromBits`-wide values into `toBits`-wide values.
 *
 * Returns null on invalid input: a value that does not fit `fromBits`, or —
 * when `pad` is false — leftover bits that are too many or non-zero.
 *
 * The range test is written as a comparison rather than a shift so that inputs
 * far beyond 32 bits (e.g. `--c 99999999999`) still reject cleanly instead of
 * wrapping the way JS bitwise operators would.
 */
export function convertBits(data, fromBits, toBits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << toBits) - 1;
  const maxAcc = (1 << (fromBits + toBits - 1)) - 1;
  const limit = 2 ** fromBits;

  for (const value of data) {
    if (value < 0 || value >= limit) return null;
    acc = ((acc << fromBits) | value) & maxAcc;
    bits += fromBits;
    while (bits >= toBits) {
      bits -= toBits;
      ret.push((acc >> bits) & maxv);
    }
  }

  if (pad) {
    if (bits) ret.push((acc << (toBits - bits)) & maxv);
  } else if (bits >= fromBits || ((acc << (toBits - bits)) & maxv)) {
    return null;
  }

  return ret;
}

