/**
 * The BCH checksum machinery behind Bech32.
 *
 * All intermediate values stay below 2^31, so plain JS bitwise operators are
 * exact here — no wider integer type is needed.
 */

const GENERATOR = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

/** The BCH generator polynomial modulus over the 5-bit values. */
export function bech32Polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < 5; i += 1) {
      if ((top >> i) & 1) chk ^= GENERATOR[i];
    }
  }
  return chk;
}

/**
 * Expand the human-readable part into checksum input: high bits, a zero
 * separator, then low bits.  Iterates by code point, like Python's `for x in
 * hrp`, so non-ASCII input is folded the same way (such input is rejected
 * later by the round-trip check, but the intermediate values still match).
 */
export function bech32HrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const ch of hrp) {
    const code = ch.codePointAt(0);
    high.push(code >> 5);
    low.push(code & 31);
  }
  return [...high, 0, ...low];
}

/** True when the trailing checksum of `data` is valid for `hrp`. */
export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod([...bech32HrpExpand(hrp), ...data]) === 1;
}

/** Compute the six trailing checksum values. */
export function bech32CreateChecksum(hrp, data) {
  const values = [...bech32HrpExpand(hrp), ...data];
  const polymod = bech32Polymod([...values, 0, 0, 0, 0, 0, 0]) ^ 1;
  const checksum = [];
  for (let i = 0; i < 6; i += 1) {
    checksum.push((polymod >> (5 * (5 - i))) & 31);
  }
  return checksum;
}

