/**
 * Bech32 string encoding and decoding.
 */

import { charsetAt, charsetIndexOf } from './charset.mjs';
import { bech32CreateChecksum, bech32VerifyChecksum } from './checksum.mjs';

// The human-readable part is limited to 83 characters (BIP-173).  Note that
// this build imposes no limit on the *total* length, so addresses longer than
// 90 characters encode successfully.
const MAX_HRP_LENGTH = 83;

/** Join the data values and their checksum into "<hrp>1<data><checksum>". */
export function bech32Encode(hrp, data) {
  const combined = [...data, ...bech32CreateChecksum(hrp, data)];
  let body = '';
  for (const value of combined) body += charsetAt(value);
  return `${hrp}1${body}`;
}

/**
 * Validate a Bech32 string.
 *
 * Returns `[hrp, data]` with the six checksum values stripped, or
 * `[null, null]` when the string is malformed.
 */
export function bech32Decode(bech) {
  for (const ch of bech) {
    const code = ch.codePointAt(0);
    if (code < 33 || code > 126) return [null, null];
  }
  if (bech.toLowerCase() !== bech && bech.toUpperCase() !== bech) {
    return [null, null];
  }

  const lowered = bech.toLowerCase();
  const pos = lowered.lastIndexOf('1');
  if (pos < 1 || pos + 7 > lowered.length) return [null, null];

  const hrp = lowered.slice(0, pos);
  if (hrp.length > MAX_HRP_LENGTH) return [null, null];

  const body = lowered.slice(pos + 1);
  const data = [];
  for (const ch of body) {
    const value = charsetIndexOf(ch);
    if (value === -1) return [null, null];
    data.push(value);
  }

  if (!bech32VerifyChecksum(hrp, data)) return [null, null];

  return [hrp, data.slice(0, -6)];
}

