/**
 * Segwit address encoding — the `bech32.encode` / `bech32.decode` entry points.
 */

import { bech32Decode, bech32Encode } from './bech32.mjs';
import { convertBits } from './convertbits.mjs';

/**
 * Decode a segwit address, returning `[witnessVersion, program]` or
 * `[null, null]`.
 */
export function decode(hrp, addr) {
  const [hrpGot, data] = bech32Decode(addr);
  if (hrpGot !== hrp) return [null, null];

  const decoded = convertBits(data.slice(1), 5, 8, false);
  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }
  const witver = data[0];
  if (witver > 16) return [null, null];
  if (witver === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }
  return [witver, decoded];
}

/**
 * Encode a segwit address, or return null when the result would not decode
 * back to a valid witness version and program.
 */
export function encode(hrp, witver, witprog) {
  const converted = convertBits(witprog, 8, 5);
  if (converted === null) return null;

  const ret = bech32Encode(hrp, [witver, ...converted]);
  const [checkedVersion] = decode(hrp, ret);
  if (checkedVersion === null) return null;
  return ret;
}

