#!/usr/bin/env bash
# Randomised differential fuzz over stdout + exit code.
PY=/workspace/dataset/test4_executable
N=${1:-400}
pass=0; fail=0

for _ in $(seq 1 "$N"); do
  # random hrp: length 0..6 from a mix of legal, illegal and boundary chars
  a=$(node -e '
    const pool = "abcdefghijklmnopqrstuvwxyz0123456789!~{}-_.ABZ 1";
    const n = Math.floor(Math.random() * 7);
    let s = "";
    for (let i = 0; i < n; i++) s += pool[Math.floor(Math.random() * pool.length)];
    process.stdout.write(s);
  ')
  b=$((RANDOM % 70 - 35))
  c=$(node -e '
    const n = Math.floor(Math.random() * 44);
    const vals = [];
    for (let i = 0; i < n; i++) {
      const r = Math.random();
      vals.push(r < 0.08 ? Math.floor(Math.random() * 600) - 40
                         : Math.floor(Math.random() * 256));
    }
    process.stdout.write(vals.join(","));
  ')

  po=$("$PY" --a "$a" --b "$b" --c "$c" 2>/dev/null); prc=$?
  jo=$(node /output/test4.mjs --a "$a" --b "$b" --c "$c" 2>/dev/null); jrc=$?
  if [ "$po" = "$jo" ] && [ "$prc" = "$jrc" ]; then
    pass=$((pass+1))
  else
    fail=$((fail+1))
    echo "MISMATCH a=[$a] b=[$b] c=[$c]"
    echo "   py(rc=$prc): [$po]"
    echo "   js(rc=$jrc): [$jo]"
  fi
done

echo "----------------------------------------"
echo "fuzz: pass=$pass fail=$fail"
[ "$fail" -eq 0 ]

